		int filter = fixture.equivalentFilter(left, fixture.trueScalar);
		clearInvocations(fixture.relations);
		fixture.rules.apply(filter, 4);
		verify(fixture.relations, times(1)).childGroupId(forward, 1);
		verify(fixture.relations, times(1)).childGroupId(reversed, 0);
		verify(fixture.relations, times(1)).childGroupId(outer, 1);
