	@Test
	void filterLiftingPreservesValuesUnionOptionalAndNestedBags() {
		Model data = model();
		add(data, "s1", "p", iri("o1"));
		add(data, "s2", "p", iri("o2"));
		add(data, "s1", "q", iri("q1"));
		add(data, "s1", "q", iri("q2"));
		PackedPredicateRangeProvider ranges = new PackedPredicateRangeProvider() {
			@Override
			public boolean describeObjectRange(IRI predicate, PackedPredicateRange output) {
				if (!predicate.equals(iri("p")) && !predicate.equals(iri("q"))) {
					return false;
				}
				output.setState(PackedPredicateRange.STATE_KNOWN);
				output.setKindBits(PackedPredicateRange.KIND_IRI);
				output.setFinite(true);
				output.addFiniteValue(iri(predicate.equals(iri("p")) ? "o1" : "q1"));
				output.addFiniteValue(iri(predicate.equals(iri("p")) ? "o2" : "q2"));
				return true;
			}

			@Override
			public long predicateRangeVersion() {
				return 1L;
			}
		};
		assertPackedPlanPreservesResults(data,
				"SELECT ?s WHERE { { ?s :p ?o FILTER(isIRI(?o)) } VALUES ?o { :o1 :o2 } }",
				SUBJECT_LOOKUP_COSTS, ranges, List.of("s=urn:t:s1", "s=urn:t:s2"));
		assertPackedPlanPreservesResults(data,
				"SELECT ?s WHERE { { { ?s :p ?o FILTER(isIRI(?o)) } FILTER(?o != :absent) } "
						+ "VALUES ?o { :o1 } }",
				SUBJECT_LOOKUP_COSTS, ranges, List.of("s=urn:t:s1"));
		assertPackedPlanPreservesResults(data,
				"SELECT ?s WHERE { { ?s :p ?o FILTER(isIRI(?o)) } "
						+ "{ { VALUES ?o { :o1 :o2 } } UNION { VALUES ?o { :o1 } } } }",
				SUBJECT_LOOKUP_COSTS, ranges, List.of("s=urn:t:s1", "s=urn:t:s1", "s=urn:t:s2"));
		assertPackedPlanPreservesResults(data,
				"SELECT ?s WHERE { { ?s :p ?o FILTER(isIRI(?o)) } "
						+ "OPTIONAL { ?s :q ?x FILTER(isIRI(?x)) } VALUES ?o { :o1 :o2 } }",
				SUBJECT_LOOKUP_COSTS, ranges, List.of("s=urn:t:s1", "s=urn:t:s1", "s=urn:t:s2"));
		assertPackedPlanPreservesResults(data,
				"SELECT ?s WHERE { { { ?s :p ?o FILTER(isIRI(?o)) } VALUES ?o { :o1 } } UNION "
						+ "{ { ?s :p ?o FILTER(isIRI(?o)) } VALUES ?o { :o1 :o2 } } }",
				SUBJECT_LOOKUP_COSTS, ranges, List.of("s=urn:t:s1", "s=urn:t:s1", "s=urn:t:s2"));
	}

